"""mkdocs hook: draw the figures of the explanations that are generated by a script.

``docs/diagrams/make_flow_algorithm_figures.py`` draws the figures of the flow cartogram algorithm explanation with the
colors of the default plot style. They are written to ``docs/generated/diagrams``, which is not committed, like the
output of the gallery, so they follow the style when it changes.
"""

import importlib.util
from pathlib import Path


def on_pre_build(config):
    docs = Path(config["docs_dir"])
    script = docs / "diagrams" / "make_flow_algorithm_figures.py"
    spec = importlib.util.spec_from_file_location("make_flow_algorithm_figures", script)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.generate(docs / "generated" / "diagrams")
